from AlgorithmImports import *
from datetime import timedelta


class SpyFiveMinuteCallCrossover(QCAlgorithm):
    # Change or override with a Lean parameter named "profit_target_return".
    DEFAULT_PROFIT_TARGET_RETURN = 0.50

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        parameter = self.GetParameter("profit_target_return")
        self.profit_target_return = (
            float(parameter) if parameter else self.DEFAULT_PROFIT_TARGET_RETURN
        )

        self.spy = self.AddEquity("SPY", Resolution.Minute).Symbol
        self.Securities[self.spy].SetDataNormalizationMode(DataNormalizationMode.Raw)

        option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = option.Symbol
        option.SetFilter(
            lambda universe: universe.Strikes(-100, 100).Expiration(
                timedelta(days=0), timedelta(days=365)
            )
        )

        self.fast_closes = []
        self.slow_closes = []
        self.previous_fast = None
        self.previous_slow = None
        self.pending_crossover_time = None

        self.held_contract = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.entry_price = None
        self.no_entry_date = None
        self.spy_liquidation_order_id = None

        self.five_minute_consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.five_minute_consolidator.DataConsolidated += self._on_five_minute_bar
        self.SubscriptionManager.AddConsolidator(self.spy, self.five_minute_consolidator)

    def OnData(self, data: Slice):
        self._liquidate_unexpected_spy_position()

        if self.held_contract is not None:
            self._process_expiration_safety()
            self._process_time_stop()
            self._process_profit_target(data)

        if self.pending_crossover_time is None:
            return

        crossover_time = self.pending_crossover_time
        self.pending_crossover_time = None

        if crossover_time != self.Time:
            return

        if self.no_entry_date == self.Time.date():
            return

        if self.held_contract is not None or self._entry_order_is_open():
            return

        self._submit_entry_from_current_chain(data)

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status in (OrderStatus.Invalid, OrderStatus.Canceled):
            if order_event.OrderId == self.entry_order_id:
                self.entry_order_id = None
            if order_event.OrderId == self.exit_order_id:
                self.exit_order_id = None
            return

        if order_event.Status != OrderStatus.Filled:
            return

        if order_event.OrderId == self.entry_order_id and order_event.FillQuantity > 0:
            self.held_contract = order_event.Symbol
            self.entry_price = float(order_event.FillPrice)
            self.Debug(
                f"ENTRY filled {order_event.Symbol} at {self.entry_price:.2f}"
            )

            ticket = self.Transactions.GetOrderTicket(self.entry_order_id)
            if ticket.Status == OrderStatus.Filled:
                self.entry_order_id = None

        if order_event.OrderId == self.exit_order_id:
            quantity = self.Portfolio[order_event.Symbol].Quantity
            if quantity == 0:
                self.Debug(f"EXIT filled {order_event.Symbol}")
                self.held_contract = None
                self.entry_price = None
                self.exit_order_id = None

        if order_event.Symbol == self.spy and self.Portfolio[self.spy].Quantity != 0:
            self.Debug("Unexpected SPY exercise/assignment position; liquidating.")
            self._liquidate_unexpected_spy_position()

    def _on_five_minute_bar(self, sender, bar: TradeBar):
        # The consolidator is driven solely by received minute bars. Missing
        # intervals produce no synthetic update.
        self.fast_closes.append(float(bar.Close))
        self.slow_closes.append(float(bar.Close))

        if len(self.fast_closes) > 5:
            self.fast_closes.pop(0)
        if len(self.slow_closes) > 20:
            self.slow_closes.pop(0)

        if len(self.fast_closes) < 5 or len(self.slow_closes) < 20:
            return

        fast = sum(self.fast_closes) / 5.0
        slow = sum(self.slow_closes) / 20.0

        bullish = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        bar_end = bar.EndTime
        eligible_time = (
            (bar_end.hour, bar_end.minute) >= (9, 45)
            and (bar_end.hour, bar_end.minute) <= (14, 30)
        )

        if bullish and eligible_time:
            self.pending_crossover_time = bar_end

    def _submit_entry_from_current_chain(self, data: Slice):
        spy_price = float(self.Securities[self.spy].Price)
        if spy_price <= 0:
            self.Debug("ENTRY skipped: SPY has no valid current price.")
            return

        chain = None
        for canonical_symbol, candidate_chain in data.OptionChains.items():
            if canonical_symbol == self.option_symbol:
                chain = candidate_chain
                break

        if chain is None:
            self.Debug("ENTRY skipped: no current SPY option chain.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        contracts = list(chain.Contracts.Values)

        valid_expiries = sorted(
            {
                contract.Expiry.date()
                for contract in contracts
                if contract.Expiry.date() >= minimum_expiry
            }
        )

        if not valid_expiries:
            self.Debug("ENTRY skipped: no expiry at least seven calendar days away.")
            return

        selected_expiry = valid_expiries[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract
            for contract in contracts
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug("ENTRY skipped: no qualifying call at selected expiry.")
            return

        selected = min(
            candidates,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )

        ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = ticket.OrderId
        self.Debug(
            f"ENTRY submitted {selected.Symbol}, expiry {selected_expiry}, "
            f"strike {float(selected.Strike):.2f}"
        )

    def _process_profit_target(self, data: Slice):
        if self.entry_price is None or self.exit_order_id is not None:
            return

        contract = self._current_contract(data, self.held_contract)
        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        target = self.entry_price * (1.0 + self.profit_target_return)

        if midpoint >= target:
            self._submit_exit("profit target")

    def _process_time_stop(self):
        if self.exit_order_id is not None or self.held_contract is None:
            return

        expiry = self.held_contract.ID.Date.date()
        prior_trading_day = self.Securities[self.spy].Exchange.Hours.GetPreviousTradingDay(
            self.held_contract.ID.Date
        ).date()

        if (
            self.Time.date() == prior_trading_day
            and self.Time.hour == 15
            and self.Time.minute == 45
        ):
            self._submit_exit("15:45 pre-expiration time stop")

    def _process_expiration_safety(self):
        if self.exit_order_id is not None or self.held_contract is None:
            return

        expiry = self.held_contract.ID.Date.date()
        if self.Time.date() >= expiry:
            self.no_entry_date = self.Time.date()
            self._submit_exit("expiration safety")

    def _submit_exit(self, reason: str):
        if self.held_contract is None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            self.held_contract = None
            self.entry_price = None
            return

        self._cancel_other_exit_orders()
        ticket = self.MarketOrder(self.held_contract, -quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug(f"EXIT submitted {self.held_contract}: {reason}")

    def _cancel_other_exit_orders(self):
        if self.exit_order_id is None:
            return

        ticket = self.Transactions.GetOrderTicket(self.exit_order_id)
        if ticket is not None and ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
        ):
            ticket.Cancel("Replacing exit order")

        self.exit_order_id = None

    def _entry_order_is_open(self) -> bool:
        if self.entry_order_id is None:
            return False

        ticket = self.Transactions.GetOrderTicket(self.entry_order_id)
        if ticket is None:
            self.entry_order_id = None
            return False

        if ticket.Status in (OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid):
            self.entry_order_id = None
            return False

        return True

    def _current_contract(self, data: Slice, symbol: Symbol):
        for canonical_symbol, chain in data.OptionChains.items():
            if canonical_symbol != self.option_symbol:
                continue

            if symbol in chain.Contracts:
                return chain.Contracts[symbol]

        return None

    def _liquidate_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            self.spy_liquidation_order_id = None
            return

        if self.spy_liquidation_order_id is not None:
            ticket = self.Transactions.GetOrderTicket(self.spy_liquidation_order_id)
            if ticket is not None and ticket.Status not in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            ):
                return

        self.Debug("Unexpected SPY equity position; submitting liquidation.")
        self.spy_liquidation_order_id = self.MarketOrder(self.spy, -quantity).OrderId
